body.text_2:
@concat(
  'Confidence score - ',
  string(outputs('Select')?['body'][0]?['cmdspp_confidencescore']),
  ' with ',
  outputs('Select')?['body'][0]?['cmdspp_riskcategory'],
  ' Risk.',
  if(
    greater(
      length(
        trim(
          concat(
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_oigleie_screening_status'], 'No Federal Exclusions Found')), 'OIG/LEIE, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_sam_exclu_screening_status'], 'No Active Exclusion Found')), 'SAM, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_tin_screening_status'], 'Legal Name and TIN/SSN Matched')), 'IRS/TIN, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_nppes_screening_status'], 'NPI Active')), 'NPI / Taxonomy, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_pecos_screening_status'], 'Medicare Enrollment Approved')), 'PECOS, ', ''),
            if(not(startsWith(coalesce(outputs('Select')?['body'][0]?['cmdspp_p_clia_screening_status'], ''), 'Certificate Active')), 'CLIA, ', ''),
            if(not(startsWith(coalesce(outputs('Select')?['body'][0]?['cmdspp_p_dea_screening_status'], ''), 'Registration Valid')), 'DEA, ', ''),
            if(not(startsWith(coalesce(outputs('Select')?['body'][0]?['cmdspp_p_license_screening_status'], ''), 'License Active')), 'State License, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_onership_screening_status'], 'Ownership valid')), 'Ownership, ', '')
          )
        )
      ),
      0
    ),
    concat(
      ' Screening Exceptions Found for ',
      substring(
        trim(
          concat(
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_oigleie_screening_status'], 'No Federal Exclusions Found')), 'OIG/LEIE, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_sam_exclu_screening_status'], 'No Active Exclusion Found')), 'SAM, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_tin_screening_status'], 'Legal Name and TIN/SSN Matched')), 'IRS/TIN, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_nppes_screening_status'], 'NPI Active')), 'NPI / Taxonomy, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_pecos_screening_status'], 'Medicare Enrollment Approved')), 'PECOS, ', ''),
            if(not(startsWith(coalesce(outputs('Select')?['body'][0]?['cmdspp_p_clia_screening_status'], ''), 'Certificate Active')), 'CLIA, ', ''),
            if(not(startsWith(coalesce(outputs('Select')?['body'][0]?['cmdspp_p_dea_screening_status'], ''), 'Registration Valid')), 'DEA, ', ''),
            if(not(startsWith(coalesce(outputs('Select')?['body'][0]?['cmdspp_p_license_screening_status'], ''), 'License Active')), 'State License, ', ''),
            if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_onership_screening_status'], 'Ownership valid')), 'Ownership, ', '')
          )
        ),
        0,
        sub(
          length(
            trim(
              concat(
                if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_oigleie_screening_status'], 'No Federal Exclusions Found')), 'OIG/LEIE, ', ''),
                if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_sam_exclu_screening_status'], 'No Active Exclusion Found')), 'SAM, ', ''),
                if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_tin_screening_status'], 'Legal Name and TIN/SSN Matched')), 'IRS/TIN, ', ''),
                if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_nppes_screening_status'], 'NPI Active')), 'NPI / Taxonomy, ', ''),
                if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_pecos_screening_status'], 'Medicare Enrollment Approved')), 'PECOS, ', ''),
                if(not(startsWith(coalesce(outputs('Select')?['body'][0]?['cmdspp_p_clia_screening_status'], ''), 'Certificate Active')), 'CLIA, ', ''),
                if(not(startsWith(coalesce(outputs('Select')?['body'][0]?['cmdspp_p_dea_screening_status'], ''), 'Registration Valid')), 'DEA, ', ''),
                if(not(startsWith(coalesce(outputs('Select')?['body'][0]?['cmdspp_p_license_screening_status'], ''), 'License Active')), 'State License, ', ''),
                if(not(equals(outputs('Select')?['body'][0]?['cmdspp_p_onership_screening_status'], 'Ownership valid')), 'Ownership, ', '')
              )
            )
          ),
          1
        )
      ),
      '.'
    ),
    ''
  )
)
